package com.example.data.repository

import com.example.data.export.PostmanCollectionCodec
import org.junit.After
import org.junit.Assert.*
import org.junit.Test

/**
 * Code-review fix (SHOULD-FIX) -- a Postman import's requests carry a `folderId` generated by
 * [PostmanCollectionCodec.import] pointing at one of its [PostmanCollectionCodec.ImportResult]
 * folders, but until [ApiCollectionsRepository.addFolders] existed, only the requests were ever
 * saved -- the folders themselves were never added to [ApiCollectionsRepository.folders], so
 * every imported request's `folderId` was a dangling reference to a folder that only existed in
 * the import's toast message, not in the repository.
 *
 * This exercises the same sequence `SavedApisScreen`'s import launcher now performs: import,
 * then [ApiCollectionsRepository.addFolders] BEFORE [ApiCollectionsRepository.saveRequest].
 *
 * No Robolectric needed for [addFolders] itself, but [PostmanCollectionCodec.import] parses real
 * JSON via `org.json`, which the plain android.jar stub doesn't implement -- so this class runs
 * under Robolectric, matching [com.example.data.export.PostmanCollectionCodecTest]'s rationale.
 */
@org.junit.runner.RunWith(org.robolectric.RobolectricTestRunner::class)
class ApiCollectionsRepositoryAddFoldersTest {

    private val createdRequestIds = mutableListOf<String>()

    @After
    fun tearDown() {
        createdRequestIds.forEach { ApiCollectionsRepository.deleteRequest(it) }
        createdRequestIds.clear()
    }

    private val collectionWithOneFolder = """
        {
          "info": {"name": "Folder Import Test", "schema": "https://schema.getpostman.com/json/collection/v2.1.0/collection.json"},
          "item": [
            {
              "name": "Orders Folder",
              "item": [
                {"name": "List Orders", "request": {"method": "GET", "url": "https://example.com/orders"}},
                {"name": "Create Order", "request": {"method": "POST", "url": "https://example.com/orders"}}
              ]
            }
          ]
        }
    """.trimIndent()

    @Test
    fun `addFolders makes an imported request's folderId resolve to a real folder`() {
        val result = PostmanCollectionCodec.import(collectionWithOneFolder)
        assertEquals(1, result.folders.size)
        assertEquals(2, result.requests.size)

        ApiCollectionsRepository.addFolders(result.folders)
        result.requests.forEach {
            ApiCollectionsRepository.saveRequest(it)
            createdRequestIds.add(it.id)
        }

        val folderIds = ApiCollectionsRepository.folders.value.map { it.id }.toSet()
        val savedFolderId = result.folders.first().id
        assertTrue("the imported folder must actually exist in the repository", savedFolderId in folderIds)

        result.requests.forEach { req ->
            assertNotNull("request \"${req.name}\" must have a folderId", req.folderId)
            assertTrue(
                "request \"${req.name}\"'s folderId (${req.folderId}) must resolve to a real folder",
                req.folderId in folderIds,
            )
        }
    }

    @Test
    fun `addFolders does not duplicate a folder whose id is already present`() {
        val first = PostmanCollectionCodec.import(collectionWithOneFolder)
        ApiCollectionsRepository.addFolders(first.folders)
        val countAfterFirst = ApiCollectionsRepository.folders.value.size

        // Calling addFolders again with the exact same ApiFolderItem (same id) must not create
        // a duplicate entry.
        ApiCollectionsRepository.addFolders(first.folders)
        assertEquals(countAfterFirst, ApiCollectionsRepository.folders.value.size)
    }

    @Test
    fun `addFolders with an empty list is a no-op`() {
        val before = ApiCollectionsRepository.folders.value.size
        ApiCollectionsRepository.addFolders(emptyList())
        assertEquals(before, ApiCollectionsRepository.folders.value.size)
    }
}
